"""Approfondissement sourcé des DX.5 à DX.10. Aucun chiffre hors pages lues le 24.10.2026."""
from gen_lot208_b import block, p, table, td

NB = "\u00a0"


def fen(title, paras):
    return block(title, "".join(p(x) for x in paras))


def q61(point, question, wrong, right, dit, dossier):
    return fen(
        f"Question 6.1 — point {point}",
        [
            question,
            "La copie qui perd les points affirme ceci. " + wrong,
            "La copie juste reprend le fil, et elle s'arrête où la page s'arrête. " + right,
            "À la personne, la phrase peut être celle-ci. " + dit,
            "Dans le dossier, une seule phrase porte la décision. " + dossier,
        ],
    )


def q62(texte):
    return fen("Question 6.2 — ce que ce cours permet, et ce qu'il refuse encore", texte)


def chaine(title, paras):
    return fen(title, paras)


